import { useState } from "react";
import { changePassword } from "../../api/authApi";
import { useToast, apiErrorMessage } from "../../context/ToastContext";

export default function ChangePassword() {
  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [saving, setSaving] = useState(false);
  const toast = useToast();

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      toast.error("New password and confirmation do not match");
      return;
    }
    setSaving(true);
    try {
      await changePassword(oldPassword, newPassword);
      toast.success("Password updated successfully");
      setOldPassword(""); setNewPassword(""); setConfirmPassword("");
    } catch (err) {
      toast.error(apiErrorMessage(err, "Could not change password"));
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <div className="page-head">
        <div>
          <span className="eyebrow">Security</span>
          <h1>Change Password</h1>
          <p className="desc">Use this after your first login with a temporary password, or anytime you'd like to rotate it.</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="card card-pad" style={{ maxWidth: 420 }}>
        <div className="form-field full">
          <label>Current Password<span className="req">*</span></label>
          <input type="password" value={oldPassword} onChange={(e) => setOldPassword(e.target.value)} required />
        </div>
        <div className="form-field full">
          <label>New Password<span className="req">*</span></label>
          <input type="password" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} required minLength={6} />
        </div>
        <div className="form-field full">
          <label>Confirm New Password<span className="req">*</span></label>
          <input type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} required minLength={6} />
        </div>
        <button type="submit" className="btn btn-brass btn-block" disabled={saving} style={{ marginTop: 8 }}>
          {saving && <span className="btn-spinner" />}
          {saving ? "Updating…" : "Update Password"}
        </button>
      </form>
    </>
  );
}
